const input = $('Execute Sub Workflow Trigger').first().json;
const execResult = items[0].json;
const exitCode = execResult.exitCode || 0;
const stdout = execResult.stdout || '';

let parsed = {};
try { parsed = JSON.parse(stdout); } catch(e) { parsed = { raw: stdout }; }

return [{json: {
  ...input,
  launch_exit_code: exitCode,
  launch_result: parsed,
  workspace_path: parsed.workspace_path || '',
  launch_failed: exitCode !== 0
}}];

const input = $('C1 -- Parse Launch Result').first().json;
const missionId = input.mission_id;
const orthoCheckDir = $env.MIPMAP_WORKSPACE + '\\' + missionId + '\\result';

// Track poll_attempt via workflow static data
const staticData = $getWorkflowStaticData('global');
staticData.poll_attempt = (staticData.poll_attempt || 0) + 1;

return [{
  json: {
    mission_id: missionId,
    ortho_check_dir: orthoCheckDir,
    mission_path: input.folder_path,
    processing_job_id: input.processing_job_id,
    poll_attempt: staticData.poll_attempt,
    max_attempts: 120
  }
}];

return [{json: {
  status: 'failed',
  reason: 'mipmap_timeout',
  poll_attempts: $('C2 -- Build Ortho Path').item.json.poll_attempt,
  max_attempts: 120,
  mission_id: $('C2 -- Build Ortho Path').item.json.mission_id,
  message: 'MipMap did not produce output within 2 hours (120 attempts x 60s)'
}}];

const orthoCheckDir = $('C2 -- Build Ortho Path').item.json.ortho_check_dir;
const stdout = items[0].json.stdout || '';
// Take the first .tif filename from dir output
const filename = stdout.trim().split('\n')[0].trim();
const sourcePath = orthoCheckDir + '\\' + filename;

return [{json: {
  source_path: sourcePath,
  ortho_filename: filename,
  mission_path: $('C2 -- Build Ortho Path').item.json.mission_path,
  mission_id: $('C2 -- Build Ortho Path').item.json.mission_id,
  processing_job_id: $('C2 -- Build Ortho Path').item.json.processing_job_id
}}];

const input = $('C3 -- Build Harvest Command').first().json;
const execResult = items[0].json;
const exitCode = execResult.exitCode || 0;
const stdout = execResult.stdout || '';

let parsed = {};
try { parsed = JSON.parse(stdout); } catch(e) { parsed = { raw: stdout }; }

return [{json: {
  ...input,
  harvest_exit_code: exitCode,
  harvest_result: parsed,
  destination_path: parsed.destination_path || '',
  harvest_failed: exitCode !== 0
}}];

return [{json: {
  status: 'complete',
  vegetation_triggered: false,
  mission_id: $('C3 -- Parse Harvest Result').first().json.mission_id
}}];

return [{json: {
  status: 'complete',
  vegetation_triggered: true,
  mission_id: $('C3 -- Parse Harvest Result').first().json.mission_id
}}];
